1	import AppKit
2	import Defaults
3	
4	/// Hosts one `QuickSwitcherReducer` session and connects it to the world (issue #132, T10): it freezes
5	/// the item list at open, arms the reveal, polls the trigger modifier, watches for the ways a session
6	/// can die, and performs the commit. The reducer decides; this only executes.
7	///
8	/// The panel is deliberately **not** owned here. `onReveal` / `onCursorMoved` / `onEnd` are the seam
9	/// T11 hangs the rail on, which keeps this whole class testable with no window on screen.
10	@MainActor
11	final class QuickSwitcherController {
12	  static let shared = QuickSwitcherController()
13	
14	  /// One frozen candidate. Frozen at open so the list can't reshuffle under the cursor mid-gesture —
15	  /// MRU order changes the instant anything is selected, which is exactly what a commit does.
16	  enum Item {
17	    case workroom(WorkroomSlot)
18	    case pane(TerminalTab)
19	  }
20	
21	  // MARK: Injected seams (production defaults; tests replace)
22	
23	  /// The live hardware modifier snapshot. A *global* read on purpose: it stays true through menu
24	  /// tracking, Mission Control and another app holding focus, all of which starve a local
25	  /// `flagsChanged` monitor. Masked to the device-independent bits — the raw value carries
26	  /// left/right-key and numeric-pad bits that never match a configured trigger.
27	  var flagsProvider: () -> NSEvent.ModifierFlags = {
28	    NSEvent.modifierFlags.intersection(.deviceIndependentFlagsMask)
29	  }
30	
31	  /// D16: with VoiceOver running the switcher never opens a session — see `handleTrigger`.
32	  var voiceOverEnabled: () -> Bool = { NSWorkspace.shared.isVoiceOverEnabled }
33	
34	  /// Where the pointer is. Read at reveal *and* at each hover so D17's threshold compares two values
35	  /// from the same source — a test that injected only the hover position would be measuring against
36	  /// the real mouse, wherever the machine's cursor happens to sit.
37	  var pointerProvider: () -> NSPoint = { NSEvent.mouseLocation }
38	
39	  /// Speaks a destination on the VoiceOver path. Replaced in tests to assert what was announced.
40	  var announce: (String) -> Void = { message in
41	    NSAccessibility.post(
42	      element: NSApp as Any, notification: .announcementRequested,
43	      userInfo: [
44	        .announcement: message,
45	        .priority: NSAccessibilityPriorityLevel.high.rawValue,
46	      ])
47	  }
48	
49	  /// Starts the two production timers. Injected so tests can drive `revealTimerFired` / `poll`
50	  /// directly instead of waiting out real time.
51	  var startTimers: (QuickSwitcherController) -> Void = { controller in
52	    controller.installRealTimers()
53	  }
54	  var stopTimers: () -> Void = {}
55	
56	  // MARK: Rail seam (T11)
57	
58	  var onReveal: (([Item], Int) -> Void)?
59	  var onCursorMoved: ((Int) -> Void)?
60	  var onEnd: (() -> Void)?
61	
62	  // MARK: State
63	
64	  private(set) var reducer = QuickSwitcherReducer()
65	  private(set) var items: [Item] = []
66	  /// The window the gesture started in — the commit's "am I already here" reference.
67	  private weak var originStore: AppStore?
68	  /// The modifier that must stay held. Released ⇒ commit.
69	  private var triggerFlags: NSEvent.ModifierFlags = []
70	  private var observers: [NSObjectProtocol] = []
71	  private var pollTimer: Timer?
72	  private var revealTimer: Timer?
73	  private var ceilingTimer: Timer?
74	  /// Pointer position at reveal, for D17's movement threshold.
75	  private var pointerAtReveal: NSPoint?
76	
77	  var isLive: Bool { reducer.isLive }
78	  var isRevealed: Bool { reducer.isRevealed }
79	
80	  /// How far the pointer must actually travel before hover may steer the cursor (D17).
81	  static let hoverArmDistance: CGFloat = 4
82	
83	  // MARK: Entry
84	
85	  /// The key monitor's entry point. Returns whether the event was consumed.
86	  @discardableResult
87	  func handleTrigger(
88	    _ kind: QuickSwitcherKind, reverse: Bool, in store: AppStore,
89	    registry: WindowRegistry = .shared, recency: SwitcherRecency = .shared
90	  ) -> Bool {
91	    // D16 — VoiceOver: no session, no panel. ⌃⌥ is VoiceOver's own modifier pair, a panel that can't
92	    // become key can never hold VoiceOver focus however well it narrates, and a fast Tab-Tab-Tab would
93	    // queue announcements that land *after* the commit. So this degrades to the stage-1 tap flip, which
94	    // is a complete interaction on its own, and says where it landed.
95	    if voiceOverEnabled() {
96	      let switched = QuickSwitcher.step(
97	        kind, reverse: reverse, in: store, registry: registry, recency: recency)
98	      if switched, let spoken = Self.announcement(for: kind, in: store) { announce(spoken) }
99	      return switched
100	    }
101	
102	    if isLive {
103	      apply(reducer.handle(.step(reverse: reverse)))
104	      return true
105	    }
106	
107	    let frozen = Self.collect(kind, in: store, registry: registry, recency: recency)
108	    let effect = reducer.handle(.open(kind: kind, count: frozen.count, reverse: reverse))
109	    // Under 2 items there is nothing to switch to, so the key passes through to the terminal.
110	    guard effect != .none else { return false }
111	    items = frozen
112	    originStore = store
113	    triggerFlags =
114	      (kind == .workrooms
115	      ? Defaults[.switcherWorkroomModifier] : Defaults[.switcherPaneModifier]).flags
116	    installObservers()
117	    startTimers(self)
118	    apply(effect)
119	    // A held modifier is not drivable by synthetic input (see `switcherRevealsImmediately`), so under
120	    // the fixture flag skip straight to the revealed state.
121	    if UITestFixture.switcherRevealsImmediately { revealTimerFired() }
122	    return true
123	  }
124	
125	  /// Escape while a session is live.
126	  @discardableResult
127	  func handleEscape() -> Bool {
128	    guard isLive else { return false }
129	    cancel(.escape)
130	    return true
131	  }
132	
133	  /// ←/→ while the rail is up. Returns whether it was consumed.
134	  @discardableResult
135	  func handleArrow(reverse: Bool) -> Bool {
136	    guard isLive else { return false }
137	    apply(reducer.handle(.step(reverse: reverse)))
138	    return true
139	  }
140	
141	  /// A card was hovered. Ignored until the pointer has actually moved (D17) — the reducer holds that
142	  /// rule; this only reports the movement.
143	  func point(index: Int, pointer: NSPoint? = nil) {
144	    guard isLive else { return }
145	    let location = pointer ?? pointerProvider()
146	    if let origin = pointerAtReveal,
147	      hypot(location.x - origin.x, location.y - origin.y) > Self.hoverArmDistance
148	    {
149	      pointerAtReveal = nil
150	      apply(reducer.handle(.armHover))
151	    }
152	    apply(reducer.handle(.point(index: index)))
153	  }
154	
155	  /// A card was clicked. Commits immediately; the modifier release that follows is swallowed.
156	  func clickCommit(index: Int) {
157	    guard isLive else { return }
158	    apply(reducer.handle(.commit(index: index)))
159	  }
160	
161	  func cancel(_ reason: QuickSwitcherReducer.Cancel) {
162	    guard isLive else { return }
163	    apply(reducer.handle(.cancel(reason)))
164	  }
165	
166	  // MARK: Timer / poll inputs (called by the real timers, or directly by tests)
167	
168	  func revealTimerFired() {
169	    apply(reducer.handle(.revealTimerFired))
170	  }
171	
172	  /// One 30 ms tick. The only thing that ends a held session normally.
173	  func poll() {
174	    guard isLive else { return }
175	    // Under the reveal fixture flag the "hold" is a synthetic tap, so the modifier is already up by
176	    // the time the first tick lands and the rail would vanish before anything could look at it. The
177	    // session then ends on Escape or a click, which is what those tests drive.
178	    guard !UITestFixture.switcherRevealsImmediately else { return }
179	    guard !flagsProvider().contains(triggerFlags) else { return }
180	    apply(reducer.handle(.modifierReleased))
181	  }
182	
183	  /// A window closed (or its workroom went away): drop dead candidates and tell the reducer the new
184	  /// count, which clamps the cursor or ends the session.
185	  func reconcileItems() {
186	    guard isLive else { return }
187	    items = items.filter(isAlive)
188	    apply(reducer.handle(.itemsChanged(count: items.count)))
189	  }
190	
191	  // MARK: Effects
192	
193	  private func apply(_ effect: QuickSwitcherReducer.Effect) {
194	    switch effect {
195	    case .none:
196	      break
197	    case .armReveal:
198	      break  // the timers were installed by `handleTrigger`; nothing to show yet
199	    case .reveal:
200	      // Record where the pointer already is, so a panel appearing under a stationary cursor can't
201	      // steer the selection (D17).
202	      pointerAtReveal = pointerProvider()
203	      onReveal?(items, reducer.cursor)
204	    case .moveCursor(let index):
205	      if reducer.isRevealed { onCursorMoved?(index) }
206	    case .end(let commit):
207	      let chosen = commit.flatMap { items.indices.contains($0) ? items[$0] : nil }
208	      let store = originStore
209	      teardown()
210	      onEnd?()
211	      if let chosen, let store { Self.perform(chosen, from: store) }
212	    }
213	  }
214	
215	  private func teardown() {
216	    items = []
217	    originStore = nil
218	    triggerFlags = []
219	    pointerAtReveal = nil
220	    for observer in observers { NotificationCenter.default.removeObserver(observer) }
221	    observers = []
222	    for timer in [pollTimer, revealTimer, ceilingTimer] { timer?.invalidate() }
223	    pollTimer = nil
224	    revealTimer = nil
225	    ceilingTimer = nil
226	    stopTimers()
227	  }
228	
229	  // MARK: Observers
230	
231	  private func installObservers() {
232	    let center = NotificationCenter.default
233	    observers = [
234	      // Left the app entirely (⌘Tab away, clicked another app) — don't commit somewhere they can't see.
235	      center.addObserver(
236	        forName: NSApplication.didResignActiveNotification, object: nil, queue: .main
237	      ) { [weak self] _ in
238	        MainActor.assumeIsolated { self?.cancel(.deactivated) }
239	      },
240	      center.addObserver(forName: NSWindow.willCloseNotification, object: nil, queue: .main) {
241	        [weak self] _ in
242	        // Deferred: the window is still in `allStores` *during* willClose, so a same-tick re-resolve
243	        // would keep counting the one that's going away.
244	        DispatchQueue.main.async { MainActor.assumeIsolated { self?.reconcileItems() } }
245	      },
246	    ]
247	  }
248	
249	  /// The production timers. `.common` run-loop mode is load-bearing: the default mode does not run
250	  /// during menu tracking or a modal loop, so a `.default`-mode poll would stall exactly in the cases
251	  /// the hardware-snapshot approach exists to survive, and the rail would hang until the mode exited.
252	  fileprivate func installRealTimers() {
253	    let reveal = Timer(
254	      timeInterval: Self.seconds(QuickSwitcherReducer.revealDelay), repeats: false
255	    ) { [weak self] _ in
256	      MainActor.assumeIsolated { self?.revealTimerFired() }
257	    }
258	    let poll = Timer(timeInterval: 0.03, repeats: true) { [weak self] _ in
259	      MainActor.assumeIsolated { self?.poll() }
260	    }
261	    let ceiling = Timer(
262	      timeInterval: Self.seconds(QuickSwitcherReducer.sessionCeiling), repeats: false
263	    ) { [weak self] _ in
264	      MainActor.assumeIsolated { self?.cancel(.timeout) }
265	    }
266	    for timer in [reveal, poll, ceiling] { RunLoop.main.add(timer, forMode: .common) }
267	    revealTimer = reveal
268	    pollTimer = poll
269	    ceilingTimer = ceiling
270	  }
271	
272	  private static func seconds(_ duration: Duration) -> TimeInterval {
273	    let parts = duration.components
274	    return TimeInterval(parts.seconds) + TimeInterval(parts.attoseconds) / 1e18
275	  }
276	
277	  // MARK: Items
278	
279	  static func collect(
280	    _ kind: QuickSwitcherKind, in store: AppStore, registry: WindowRegistry = .shared,
281	    recency: SwitcherRecency = .shared
282	  ) -> [Item] {
283	    switch kind {
284	    case .workrooms:
285	      return QuickSwitcher.workroomSlots(registry: registry, recency: recency).map(Item.workroom)
286	    case .panes:
287	      return QuickSwitcher.paneTabs(in: store, recency: recency).map(Item.pane)
288	    }
289	  }
290	
291	  /// Still switchable? A slot whose window has gone (or has raised a sheet since) is dead; a pane is
292	  /// checked against its origin window's live tab list. An instance method, not a static: a pane's
293	  /// liveness is only answerable against *this* session's origin store.
294	  private func isAlive(_ item: Item) -> Bool {
295	    switch item {
296	    case .workroom(let slot):
297	      guard let store = slot.store, !store.hasModalPresentation else { return false }
298	      return store.displayedWorkroomTargets().contains { $0.sid == slot.sid }
299	    case .pane(let tab):
300	      guard let store = originStore, let target = store.selectedTarget else { return false }
301	      return store.terminals.tabs(for: target).contains { $0.id == tab.id }
302	    }
303	  }
304	
305	  private static func perform(_ item: Item, from store: AppStore) {
306	    switch item {
307	    case .workroom(let slot): QuickSwitcher.commit(slot, from: store)
308	    case .pane(let tab): QuickSwitcher.commit(pane: tab.id, in: store)
309	    }
310	  }
311	
312	  /// What the VoiceOver path speaks after a tap flip: where it actually landed.
313	  private static func announcement(for kind: QuickSwitcherKind, in store: AppStore) -> String? {
314	    switch kind {
315	    case .workrooms:
316	      guard let sid = store.selectedTargetID else { return nil }
317	      return store.label(for: sid).full
318	    case .panes:
319	      guard let target = store.selectedTarget else { return nil }
320	      return store.terminals.activeTab(for: target)?.title
321	    }
322	  }
323	}
